module EntropyHelper
  def entropy_bubble_options_for(card)
    if card.entropic?
      {
        daysBeforeReminder: card.entropy.days_before_reminder,
        closesAt: card.entropy.auto_clean_at.iso8601,
        action: "Closes"
      }
    end
  end

  def stalled_bubble_options_for(card)
    if card.burst_pending_stall?
      {
        stallsAt: card.stalls_at.iso8601,
        since: card.last_active_at.iso8601
      }
    end
  end
end
EOF
cat <<'EOF' > app/javascript/controllers/bubble_controller.js
import { Controller } from "@hotwired/stimulus"
import { signedDifferenceInDays } from "helpers/date_helpers"

const REFRESH_INTERVAL = 3_600_000 // 1 hour (in milliseconds)

export default class extends Controller {
  static targets = [ "entropy", "top", "center", "bottom" ]
  static values = { entropy: Object, stalled: Object }

  #timer

  connect() {
    this.#timer = setInterval(this.update.bind(this), REFRESH_INTERVAL)
    this.update()
  }

  disconnect() {
    clearInterval(this.#timer)
  }

  update() {
    if (this.#isStalled) {
      this.#showStalled()
    } else if (this.#hasEntropy) {
      this.#showEntropy()
    } else {
      this.#hide()
    }
  }

  get #isStalled() {
    return this.hasStalledValue && new Date() >= new Date(this.stalledValue.stallsAt)
  }

  get #stalledForDays() {
    return signedDifferenceInDays(new Date(this.stalledValue.since), new Date())
  }

  get #hasEntropy() {
    return this.hasEntropyValue && this.#entropyCleanupInDays < this.entropyValue.daysBeforeReminder
  }

  get #entropyCleanupInDays() {
    return signedDifferenceInDays(new Date(), new Date(this.entropyValue.closesAt))
  }

  #showEntropy() {
    this.#render({
      top: this.#entropyCleanupInDays < 1 ? this.entropyValue.action : `${this.entropyValue.action} in`,
      center: this.#entropyCleanupInDays < 1 ? "!" : this.#entropyCleanupInDays,
      bottom: this.#entropyCleanupInDays < 1 ? "Today" : (this.#entropyCleanupInDays === 1 ? "day" : "days"),
    })
  }

  #render({ top, center, bottom }) {
    this.topTarget.innerHTML = top
    this.centerTarget.innerHTML = center
    this.bottomTarget.innerHTML = bottom

    this.#show()
  }

  #showStalled() {
    const days = this.#stalledForDays

    this.#render({
      top: "Stalled for",
      center: days,
      bottom: days === 1 ? "day" : "days"
    })
  }

  #hide() {
    this.element.toggleAttribute("hidden", true)
  }

  #show() {
    this.element.removeAttribute("hidden")
  }
}
EOF
cat <<'EOF' > app/views/cards/display/preview/_bubble.html.erb
<% stalled = card.stalled? %>
<% stalled_days = stalled ? card.stalled_days : nil %>
<%= tag.div \
      id: dom_id(card, "bubble"),
      hidden: !stalled,
      class: "bubble",
      data: {
        controller: "bubble",
        action: "turbo:morph-element->bubble#update:self",
        bubble_entropy_value: entropy_bubble_options_for(card)&.to_json,
        bubble_stalled_value: stalled_bubble_options_for(card)&.to_json
      } do %>

  <svg viewBox="0 0 200 100">
    <path id="<%= dom_id(card, "bubble-top-half") %>" fill="transparent" d="M 20,100 A 80,80 0 0,1 180,100"/>
    <text text-anchor="middle" fill="currentColor">
      <textPath href="#<%= dom_id(card, "bubble-top-half") %>" startOffset="50%" dominant-baseline="middle" data-bubble-target="top"><%= "Stalled for" if stalled %></textPath>
    </text>
  </svg>

  <span class="bubble__number" data-bubble-target="center"><%= stalled_days if stalled %></span>

  <svg viewBox="0 0 200 100">
    <path id="<%= dom_id(card, "bubble-bottom-half") %>" d="M 20,0 A 80,80 0 0,0 180,0" fill="transparent"/>
    <text text-anchor="middle" fill="currentColor">
      <textPath href="#<%= dom_id(card, "bubble-bottom-half") %>" startOffset="50%" dominant-baseline="middle" data-bubble-target="bottom"><%= "day".pluralize(stalled_days) if stalled %></textPath>
    </text>
  </svg>
<% end %>
EOF

